"""Private proposal revision form reuses reviewed terms; no silent send or overwrite."""
import json,os
from playwright.sync_api import sync_playwright,expect
import test_contract_package as package
class ProposalRevision(package.ContractPackage):
 def test_browser_revision_preserves_terms_refreshes_owner_and_requires_review(self):
  self.prepare_synthetic_owner();t,q=self.prepare();response=self.generate(t,q);self.assertEqual(response.status_code,200,response.text);source=response.json()['record'];snapshot=json.loads(source['input_snapshot']);before=self.f.sql('SELECT COUNT(*) n FROM nd_lc_document_bindings')[0]['n'];profile=self.owner_data();profile['bank']='НОВЫЙ ВЫМЫШЛЕННЫЙ БАНК';old=self.cget()['owner'];r=self.ctp('owner',data=profile,prior_id=int(old['id']) if old else 0,reviewed=True);self.assertEqual(r.status_code,200,r.text)
  with sync_playwright() as pw:
   browser=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM_BIN','/usr/bin/chromium'),args=['--no-sandbox']);context=browser.new_context(viewport={'width':375,'height':812});context.add_cookies([{'name':c.name,'value':c.value,'url':self.base} for c in self.owner.cookies]);page=context.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(self.base+'/order-workflow.php?order='+str(source['order_id'])+'&stage=proposal#document/'+str(source['id']));page.get_by_role('link',name='Подготовить новую редакцию из этой версии',exact=True).click();expect(page.locator('[name=subject]')).to_have_value(snapshot['fields']['subject']);expect(page.locator('[name=bank_name]')).to_have_value(profile['bank']);expect(page.locator('[name=owner_inn]')).to_have_value(profile['inn']);expect(page.locator('[name=client_type]')).to_have_value('person');self.assertEqual(page.locator('[name=project_id]').input_value(),str(source['project_id']));self.assertEqual(page.locator('[name=quotation_id]').input_value(),str(q['id']));rows=json.loads(page.locator('[name=payment_schedule]').input_value());self.assertEqual(sum(round(float(x['amount'])*100) for x in rows),sum(x['amount_minor'] for x in snapshot['payment_schedule']));self.assertEqual(rows[0]['gate'],snapshot['payment_schedule'][0]['gate']);review=page.get_by_role('checkbox',name='Я проверил все реквизиты, применимость НПД, основания обработки данных, цену, график и условия документа.',exact=True);expect(review).not_to_be_checked();self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM nd_lc_document_bindings')[0]['n'],before);review.check();page.get_by_role('button',name='Создать неизменяемый снимок на проверку',exact=True).click();page.get_by_role('heading',name='Коммерческое предложение · заказ №'+str(source['order_id']),exact=True).wait_for();self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM nd_lc_document_bindings')[0]['n'],before+1);latest=self.f.sql('SELECT * FROM nd_lc_document_bindings ORDER BY id DESC LIMIT 1')[0];new=json.loads(latest['input_snapshot']);self.assertEqual(new['fields']['bank_name'],profile['bank']);self.assertEqual(latest['state'],'OWNER_REVIEW');self.assertEqual(self.lg('documents/'+str(source['id'])).json()['record']['generated_hash'],source['generated_hash']);self.assertEqual(errors,[]);browser.close()
 def test_unreviewed_owner_and_cross_order_source_cannot_prefill(self):
  self.prepare_synthetic_owner();t,q=self.prepare();source=self.generate(t,q).json()['record'];old=self.cget()['owner'];self.assertEqual(self.ctp('owner',data={'full_name':'SYNTHETIC incomplete draft'},prior_id=int(old['id']) if old else 0,reviewed=False).status_code,200)
  with sync_playwright() as pw:
   browser=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM_BIN','/usr/bin/chromium'),args=['--no-sandbox']);context=browser.new_context();context.add_cookies([{'name':c.name,'value':c.value,'url':self.base} for c in self.owner.cookies]);page=context.new_page();page.goto(self.base+'/order-workflow.php?order='+str(source['order_id'])+'&stage=proposal#generate/'+str(source['id']));expect(page.locator('#lc-message')).to_contain_text('актуальные реквизиты');self.assertEqual(page.locator('[name=subject]').count(),0)
   other=self.insert("INSERT INTO nd_orders(customer_id,number,title,total_amount,currency) VALUES (?,?,'SYNTHETIC other order','0.00','RUB')",'nd_orders',[self.customer_id,'OTHER-REVISION-'+str(source['id'])]);page.goto(self.base+'/order-workflow.php?order='+str(other)+'&stage=proposal#generate/'+str(source['id']));expect(page.locator('#lc-message')).to_contain_text('друг');self.assertEqual(page.locator('[name=subject]').count(),0);browser.close()

for name in dir(package.ContractPackage):
 if name.startswith('test_'):setattr(ProposalRevision,name,None)
